public class ArchiveStreamFactory_createArchiveInputStream_TriageGen2Test {

    private ArchiveStreamFactory factory;

    @Before
    public void setUp() {
        factory = new ArchiveStreamFactory();
    }









    @Test
    public void testCreateArchiveInputStream_Jar() throws Exception {
        // JAR usually starts with PK (same as Zip in many implementations)
        // Since Zip is checked first, we rely on the factory's logic.
        // To strictly test Jar branch, we'd need a stream that fails Zip but passes Jar.
        // However, in Commons Compress, Jar matches Zip signature.
        byte[] jarContent = "PK\003\004".getBytes(StandardCharsets.UTF_8);
        InputStream in = new ByteArrayInputStream(jarContent);
        ArchiveInputStream ais = factory.createArchiveInputStream(in);
        // Because Zip is checked first in the code, it returns Zip.
        assertTrue(ais instanceof ZipArchiveInputStream || ais instanceof JarArchiveInputStream);
    }










}

